function tilingRectangle(n, m) {
  const heights = new Array(m).fill(0);
  let best = n * m;

  function place(count) {
    if (count >= best) return;
    let start = 0;
    for (let col = 1; col < m; col++) {
      if (heights[col] < heights[start]) start = col;
    }
    if (heights[start] === n) {
      best = count;
      return;
    }
    let end = start;
    while (end + 1 < m && heights[end + 1] === heights[start]) end++;
    const maxSide = Math.min(end - start + 1, n - heights[start]);
    for (let side = maxSide; side >= 1; side--) {
      for (let col = start; col < start + side; col++) heights[col] += side;
      place(count + 1);
      for (let col = start; col < start + side; col++) heights[col] -= side;
    }
  }

  place(0);
  return best;
}

