function tilingRectangle(n, m) {
  // Iterative deepening on a cell grid: try to fill it with at most `limit` squares, for limit = 1, 2, ...
  const filled = Array.from({ length: n }, () => new Array(m).fill(false));
  const fits = (r, c, s) => {
    if (r + s > n || c + s > m) return false;
    for (let i = r; i < r + s; i++) for (let j = c; j < c + s; j++) if (filled[i][j]) return false;
    return true;
  };
  const mark = (r, c, s, v) => { for (let i = r; i < r + s; i++) for (let j = c; j < c + s; j++) filled[i][j] = v; };
  const fill = (left, emptyCells) => {
    if (emptyCells === 0) return true;
    if (left === 0) return false;
    let r = -1, c = -1;
    outer: for (let i = 0; i < n; i++) for (let j = 0; j < m; j++) if (!filled[i][j]) { r = i; c = j; break outer; }
    const biggest = Math.min(n - r, m - c);
    if (emptyCells > left * biggest * biggest) return false;
    for (let s = biggest; s >= 1; s--) {
      if (!fits(r, c, s)) continue;
      mark(r, c, s, true);
      const ok = fill(left - 1, emptyCells - s * s);
      mark(r, c, s, false);
      if (ok) return true;
    }
    return false;
  };
  for (let limit = 1; ; limit++) if (fill(limit, n * m)) return limit;
}

